/**
 * Compiles the OpenStack OpenAPI specs into a compact catalog (src/catalog.json) used at runtime by the MCP tools.
 *
 * The specs are those generated by the OpenStack codegenerator and shipped with the OpenStack Rust SDK
 * (https://github.com/gtema/openstack, openstack_types/data, Apache-2.0), downloaded at a pinned commit. Services
 * without an upstream spec (Heat, Barbican) come from spec/extensions/<service-type>.json.
 *
 * Usage: npm run catalog [-- --specs ./local/data/dir] [-- --ref <git commit>]
 */
import { readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";
import { SERVICES, type ServiceInfo } from "../src/services.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "src", "catalog.json");
const EXTENSIONS_DIR = join(ROOT, "spec", "extensions");
const SPEC_REPO = "gtema/openstack";
const SPEC_DIR = "openstack_types/data";
/** Pinned so that the catalog only changes on purpose. */
const DEFAULT_REF = "a9b597a732c65412a919f5f0512127d8e0bc8c1e";
const METHODS = ["get", "head", "post", "put", "patch", "delete"] as const;
/** Headers the server sets itself; never exposed as parameters. */
const MANAGED_HEADERS = new Set(["x-auth-token", "openstack-api-version", "x-openstack-manila-api-version", "x-openstack-request-id", "x-service-token"]);

type Json = any;

const SCHEMA_KEYS = new Set([
  "type", "properties", "required", "items", "enum", "description", "allOf", "oneOf",
  "anyOf", "$ref", "format", "nullable", "default", "additionalProperties", "minimum",
  "maximum", "minLength", "maxLength", "pattern", "minItems", "maxItems",
]);

function arg(name: string): string | undefined {
  const idx = process.argv.indexOf(name);
  return idx > -1 ? process.argv[idx + 1] : undefined;
}

/** Plain text from the Markdown/RST of the specs, without the response code boilerplate. */
export function cleanText(text: unknown, max = 400): string | undefined {
  if (typeof text !== "string") return undefined;
  const plain = text
    .replace(/(Normal|Error) response codes?:[^\n]*(\n[ \t]*[a-zA-Z(][^\n:]*\(\d{3}\)[^\n]*)*/g, " ")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/<\/?[a-z][^>]*>/gi, " ")
    .replace(/[*`]+/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!plain || plain === "None") return undefined;
  return plain.length > max ? `${plain.slice(0, max - 1)}…` : plain;
}

function firstSentence(text: string | undefined): string | undefined {
  if (!text) return undefined;
  const m = text.match(/^(.{10,200}?[.!?])(\s|$)/);
  return (m ? m[1] : text.slice(0, 160)).replace(/\.$/, "");
}

/** "POST /v2.1/flavors/{id}/os-extra_specs" → "Create extra specs of flavors", for operations without description. */
function fromPath(method: string, path: string, actions: { name: string }[]): string {
  const segments = path.split("/").filter((s) => s && !/^v[\d.]+$/.test(s));
  const human = (s: string) => s.replace(/^(os|OS)-/, "").replace(/^OS-[A-Z0-9-]+:?/, "").replace(/[-_]+/g, " ");
  const literals = segments.filter((s) => !s.startsWith("{"));
  const item = segments.at(-1)?.startsWith("{") ?? false;
  if (literals.at(-1) === "action") {
    const target = literals.at(-2) ? human(literals.at(-2)!) : "resource";
    const names = actions.map((a) => a.name);
    return `Run an action on ${target}${names.length ? `: ${names.slice(0, 12).join(", ")}${names.length > 12 ? "…" : ""}` : ""}`;
  }
  const resource = literals.at(-1) ? human(literals.at(-1)!) : "resource";
  const parent = literals.length > 1 ? ` of ${human(literals.at(-2)!)}` : "";
  const verb: Record<string, string> = {
    get: item ? "Show" : "List",
    head: "Get the metadata of",
    post: "Create",
    put: item ? "Update" : "Replace",
    patch: "Update",
    delete: "Delete",
  };
  return `${verb[method] ?? method.toUpperCase()} ${resource}${parent}`;
}

function trimSchema(schema: Json, service: string): Json {
  if (Array.isArray(schema)) return schema.map((s) => trimSchema(s, service));
  if (!schema || typeof schema !== "object") return schema;
  const out: Json = {};
  for (const [key, value] of Object.entries<Json>(schema)) {
    if (!SCHEMA_KEYS.has(key)) continue;
    if (key === "description") {
      const d = cleanText(value, 200);
      if (d) out.description = d;
    } else if (key === "$ref" && typeof value === "string") {
      out.$ref = `#/components/schemas/${service}:${value.split("/").pop()}`;
    } else if (key === "properties") {
      out.properties = Object.fromEntries(Object.entries<Json>(value).map(([k, v]) => [k, trimSchema(v, service)]));
    } else if (key === "enum" && Array.isArray(value) && value.length > 40) {
      out.enum = [...value.slice(0, 40), "…"];
    } else if (typeof value === "object") {
      out[key] = trimSchema(value, service);
    } else {
      out[key] = value;
    }
  }
  return out;
}

function collectRefs(node: Json, into: Set<string>): void {
  if (Array.isArray(node)) return node.forEach((n) => collectRefs(n, into));
  if (!node || typeof node !== "object") return;
  for (const [key, value] of Object.entries(node)) {
    if (key === "$ref" && typeof value === "string") into.add(value);
    else collectRefs(value, into);
  }
}

function paramType(schema: Json): string {
  if (!schema) return "string";
  if (schema.type === "array") return `array<${schema.items?.type ?? "string"}>`;
  if (Array.isArray(schema.type)) return schema.type.filter((t: string) => t !== "null").join("|") || "string";
  return schema.type ?? (schema.enum ? "enum" : "string");
}

async function loadSpec(service: ServiceInfo, ref: string): Promise<Json | undefined> {
  if (!service.spec) return undefined;
  const local = arg("--specs");
  if (local) return parse(await readFile(join(local, service.spec), "utf8"), { maxAliasCount: -1 });
  const url = `https://raw.githubusercontent.com/${SPEC_REPO}/${ref}/${SPEC_DIR}/${service.spec}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Failed to download ${url}: HTTP ${res.status}`);
  return parse(await res.text(), { maxAliasCount: -1 });
}

async function loadExtension(service: ServiceInfo): Promise<Json | undefined> {
  try {
    return JSON.parse(await readFile(join(EXTENSIONS_DIR, `${service.type}.json`), "utf8"));
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw new Error(`Cannot read extension of ${service.type}: ${(err as Error).message}`);
  }
}

/** Action names of an /action endpoint, from the branches of its request body (one property per action). */
function actionsOf(spec: Json, bodySchema: Json): { name: string; schema: string; summary?: string }[] {
  if (!bodySchema?.oneOf || bodySchema["x-openstack"]?.discriminator !== "action") return [];
  const out = new Map<string, { name: string; schema: string; summary?: string }>();
  // A branch is either one action ({"reboot": {...}}) or a oneOf of its microversion variants: the outer schema
  // name is kept so that describe shows every variant.
  const visit = (branch: Json, outer?: string, depth = 0) => {
    const name = typeof branch?.$ref === "string" ? branch.$ref.split("/").pop() : undefined;
    const def = name ? spec.components?.schemas?.[name] : branch;
    if (!def || depth > 3) return;
    if (!def.properties && Array.isArray(def.oneOf)) {
      for (const inner of def.oneOf) visit(inner, outer ?? name, depth + 1);
      return;
    }
    for (const action of Object.keys(def.properties ?? {})) {
      if (!out.has(action)) {
        const owner = outer ?? name;
        const description = owner ? spec.components?.schemas?.[owner]?.description : undefined;
        out.set(action, { name: action, schema: owner ?? "", summary: firstSentence(cleanText(description ?? def.description, 300)) });
      }
    }
  };
  for (const branch of bodySchema.oneOf) visit(branch);
  return [...out.values()].sort((a, b) => a.name.localeCompare(b.name));
}

function compile(service: ServiceInfo, spec: Json, source: string, refs: Set<string>): Json[] {
  const sharedParams = spec.components?.parameters ?? {};
  const resolveParam = (p: Json) => (p && typeof p === "object" && p.$ref ? sharedParams[p.$ref.split("/").pop()] : p);
  const operations: Json[] = [];

  for (const [path, item] of Object.entries<Json>(spec.paths ?? {})) {
    if (path === "/" || /^\/v[\d.]+\/?$/.test(path)) continue; // version discovery documents
    for (const method of METHODS) {
      const op = item[method];
      if (!op) continue;

      const byKey = new Map<string, Json>();
      for (const p of [...(item.parameters ?? []), ...Object.values<Json>(op.parameters ?? [])].map(resolveParam)) {
        if (!p || typeof p !== "object" || !p.name || !["path", "query", "header"].includes(p.in)) continue;
        if (p.in === "header" && MANAGED_HEADERS.has(String(p.name).toLowerCase())) continue;
        byKey.set(`${p.in}:${p.name}`, p);
      }
      const params = [...byKey.values()].map((p: Json) => {
        const schema = p.schema ?? {};
        const values = schema.enum ?? schema.items?.enum;
        const description = cleanText(p.description ?? schema.description, 200);
        const mv = p["x-openstack"];
        return {
          name: p.name,
          in: p.in,
          ...(p.required || p.in === "path" ? { required: true } : {}),
          type: paramType(schema),
          ...(Array.isArray(values) && values.length ? { values: values.filter((v: unknown) => v !== null).slice(0, 40) } : {}),
          ...(description ? { description } : {}),
          ...(mv?.["min-ver"] ? { minVersion: String(mv["min-ver"]) } : {}),
          ...(mv?.["max-ver"] ? { maxVersion: String(mv["max-ver"]) } : {}),
        };
      });

      let body: Json;
      let actions: Json[] = [];
      const content = op.requestBody?.content;
      if (content) {
        const contentType = Object.keys(content)[0];
        const raw = content[contentType]?.schema ?? {};
        actions = actionsOf(spec, raw);
        const schema = trimSchema(raw, service.type);
        collectRefs(schema, refs);
        body = {
          contentType: contentType === "*" ? "application/octet-stream" : contentType,
          ...(op.requestBody.required ? { required: true } : {}),
          schema,
        };
      }

      const okResponse = Object.entries<Json>(op.responses ?? {}).find(([code]) => code.startsWith("2"));
      const responseType = okResponse ? Object.keys(okResponse[1]?.content ?? {})[0] : undefined;
      const description = cleanText(op.description, 600);
      let summary = cleanText(op.summary, 160) ?? firstSentence(description) ?? fromPath(method, path, actions);
      // Some specs only say "GET operation on /path"; actions are listed so they can be searched.
      if (/^[A-Z]+ operation on \//.test(summary) || (actions.length && !summary.includes(actions[0].name))) {
        summary = fromPath(method, path, actions);
      }
      const firstSegment = path.split("/").find((s) => s && !/^v[\d.]+$/.test(s) && !s.startsWith("{"));
      const tag = op.tags?.[0] ?? firstSegment ?? "general";
      const mv = op["x-openstack"];

      operations.push({
        id: `${service.type} ${method.toUpperCase()} ${path}`,
        service: service.type,
        method: method.toUpperCase(),
        path,
        tag: `${service.name} > ${tag}`,
        summary,
        ...(description && description !== summary ? { description } : {}),
        ...(op.deprecated ? { deprecated: true } : {}),
        ...(op["x-openstack-mcp-dangerous"] ? { dangerous: true } : {}),
        ...(source !== "upstream" ? { source } : {}),
        ...(mv?.["min-ver"] ? { minVersion: String(mv["min-ver"]) } : {}),
        ...(mv?.["max-ver"] ? { maxVersion: String(mv["max-ver"]) } : {}),
        params,
        ...(body ? { body } : {}),
        ...(actions.length ? { actions } : {}),
        ...(responseType && responseType !== "application/json" ? { responseType } : {}),
      });
    }
  }
  return operations;
}

async function main() {
  const ref = arg("--ref") ?? DEFAULT_REF;
  const operations: Json[] = [];
  const schemas: Json = {};
  const versions: Record<string, string> = {};

  for (const service of SERVICES) {
    const refs = new Set<string>();
    const pending: [Json, string][] = [];
    const upstream = await loadSpec(service, ref);
    if (upstream) pending.push([upstream, "upstream"]);
    const extension = await loadExtension(service);
    if (extension) pending.push([extension, "curated"]);
    if (!pending.length) {
      console.warn(`No spec for ${service.type}, skipped`);
      continue;
    }

    const seen = new Set<string>();
    for (const [spec, source] of pending) {
      if (source === "upstream" && spec.info?.version) versions[service.type] = String(spec.info.version);
      for (const op of compile(service, spec, source, refs)) {
        // An upstream operation wins over a curated one with the same method and path.
        if (seen.has(op.id)) continue;
        seen.add(op.id);
        operations.push(op);
      }
      // Keep only the component schemas reachable from request bodies, namespaced by service.
      const queue = [...refs];
      while (queue.length) {
        const name = queue.pop()!.split("/").pop()!;
        const local = name.slice(service.type.length + 1);
        if (schemas[name] || !spec.components?.schemas?.[local]) continue;
        schemas[name] = trimSchema(spec.components.schemas[local], service.type);
        const nested = new Set<string>();
        collectRefs(schemas[name], nested);
        queue.push(...nested);
      }
    }
    console.log(`${service.name}: ${seen.size} operations${extension ? " (with curated extension)" : ""}`);
  }

  const extensions = await readdir(EXTENSIONS_DIR).catch(() => [] as string[]);
  const catalog = {
    source: `https://github.com/${SPEC_REPO}/tree/${ref}/${SPEC_DIR}${extensions.length ? ` + spec/extensions (${extensions.length})` : ""}`,
    generatedAt: new Date().toISOString(),
    versions,
    operations,
    schemas,
  };
  await writeFile(OUT, JSON.stringify(catalog));
  console.log(`Wrote ${operations.length} operations, ${Object.keys(schemas).length} schemas to ${OUT}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
